#!/usr/bin/env python3
"""Install Caravan Profile accordion, without database changes."""
from pathlib import Path
p=Path('public/index.html')
if not p.exists() or not Path('public/checklists.js').exists():
    raise SystemExit('Run this script from the caravan-trip-planner repository root.')
html=p.read_text()
if '/caravan-profile-accordion.js' in html:
    raise SystemExit('Accordion already installed. Do not run again.')
if html.count('</head>')!=1 or html.count('</body>')!=1:
    raise SystemExit('Unexpected index.html structure; no changes made.')
css='/* Profile accordion — mobile and desktop */\n#phaseProfileForm .ux-profile-group-head{padding:0!important}\n#phaseProfileForm .cpa-toggle{\n width:100%;min-width:0;display:flex;align-items:center;\n gap:14px;text-align:left;cursor:pointer;\n border:0;background:transparent;color:inherit;\n padding:18px 20px;border-radius:0;font:inherit;\n}\n#phaseProfileForm .cpa-toggle:hover{background:#eaf4f3}\n#phaseProfileForm .cpa-toggle:focus-visible{outline:3px solid #168f99;outline-offset:-3px}\n#phaseProfileForm .cpa-toggle>div{min-width:0;flex:1}\n#phaseProfileForm .cpa-toggle h3,#phaseProfileForm .cpa-toggle p{text-align:left}\n#phaseProfileForm .cpa-chevron{margin-left:auto;flex:0 0 auto;font-size:25px;line-height:1;color:#315f68;transition:transform .18s ease}\n#phaseProfileForm .ux-profile-group[data-open="true"] .cpa-chevron{transform:rotate(180deg)}\n#phaseProfileForm .ux-profile-group[data-open="true"] .ux-profile-group-head{border-bottom:1px solid #e1ecec}\n#phaseProfileForm .ux-profile-group[data-open="false"] .ux-profile-group-head{border-bottom:0}\n#phaseProfileForm .ux-profile-fields[hidden],\n#phaseProfileForm .cpa-section-actions[hidden]{display:none!important}\n#phaseProfileSave>.phase-actions[hidden]{display:none!important}\n#phaseProfileForm .cpa-section-actions{\n display:flex;justify-content:flex-end;padding:0 20px 20px;\n}\n#phaseProfileForm .cpa-save{\n width:auto;max-width:100%;min-height:44px;padding:10px 18px;\n border:0;border-radius:10px;background:#168f99;color:#fff;\n font-size:14px;font-weight:700;cursor:pointer;\n}\n#phaseProfileForm .cpa-save:hover{background:#126f78}\n@media(max-width:650px){\n #phaseProfileForm .cpa-toggle{padding:15px 16px;gap:12px}\n #phaseProfileForm .cpa-section-actions{padding:0 16px 16px}\n #phaseProfileForm .cpa-save{width:100%}\n}\n@media(prefers-reduced-motion:reduce){\n #phaseProfileForm .cpa-chevron{transition:none}\n}\n'
js="/* Caravan Profile: accessible, collapsed-by-default sections. */\n(()=>{\n'use strict';\nconst rootId='phaseProfileForm';\nlet openIndex=-1;\nlet installed=false;\nconst esc=s=>String(s||'');\nfunction init(){\n const root=document.getElementById(rootId);\n if(!root)return;\n const form=document.getElementById('phaseProfileSave');\n if(!form)return;\n function enhance(){\n  const groups=[...root.querySelectorAll(':scope > .ux-profile-group')];\n  if(!groups.length)return;\n  groups.forEach((group,i)=>{\n   if(group.dataset.accordionReady==='1')return;\n   group.dataset.accordionReady='1';\n   const head=group.querySelector('.ux-profile-group-head');\n   const fields=group.querySelector('.ux-profile-fields');\n   if(!head||!fields)return;\n   const title=head.querySelector('h3')?.textContent||'Caravan details';\n   const button=document.createElement('button');\n   button.type='button';\n   button.className='cpa-toggle';\n   button.setAttribute('aria-label','Expand '+title);\n   const id='cpa-fields-'+i;\n   fields.id=id;\n   button.setAttribute('aria-controls',id);\n   // Move existing title and description nodes; retain original styling.\n   while(head.firstChild)button.append(head.firstChild);\n   const chevron=document.createElement('span');\n   chevron.className='cpa-chevron';\n   chevron.setAttribute('aria-hidden','true');\n   chevron.textContent='⌄';\n   button.append(chevron);\n   head.append(button);\n   const actions=document.createElement('div');\n   actions.className='cpa-section-actions';\n   const save=document.createElement('button');\n   save.type='submit';\n   save.className='cpa-save';\n   save.textContent='Save caravan details';\n   actions.append(save);\n   group.append(actions);\n   group.dataset.open='false';\n   button.setAttribute('aria-expanded','false');\n   fields.hidden=true;\n   actions.hidden=true;\n   button.addEventListener('click',()=>{\n    const isOpen=group.dataset.open==='true';\n    openIndex=isOpen?-1:i;\n    sync();\n   });\n  });\n  sync();\n }\n function sync(){\n  const groups=[...root.querySelectorAll(':scope > .ux-profile-group')];\n  groups.forEach((group,i)=>{\n   const expanded=i===openIndex;\n   group.dataset.open=String(expanded);\n   const button=group.querySelector('.cpa-toggle');\n   const fields=group.querySelector('.ux-profile-fields');\n   const actions=group.querySelector('.cpa-section-actions');\n   if(button){\n    button.setAttribute('aria-expanded',String(expanded));\n    button.setAttribute('aria-label',(expanded?'Collapse ':'Expand ')+(button.querySelector('h3')?.textContent||'Caravan details'));\n   }\n   if(fields)fields.hidden=!expanded;\n   if(actions)actions.hidden=!expanded;\n  });\n  const original=form.querySelector(':scope > .phase-actions');\n  if(original)original.hidden=true;\n }\n if(!installed){\n  installed=true;\n  const observer=new MutationObserver(records=>{\n   if(records.some(r=>r.target===root && r.type==='childList')){\n    // Re-render after successful save replaces sections; close by default.\n    openIndex=-1;\n    enhance();\n   }\n  });\n  observer.observe(root,{childList:true});\n }\n enhance();\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});\nelse init();\n})();\n"
p.write_text(html.replace('</head>','<link rel="stylesheet" href="/caravan-profile-accordion.css?v=1"></head>').replace('</body>','<script src="/caravan-profile-accordion.js?v=1" defer></script></body>'))
Path('public/caravan-profile-accordion.css').write_text(css)
Path('public/caravan-profile-accordion.js').write_text(js)
print('Caravan Profile accordion installed: all sections collapsed by default.')
print('Save button inside expanded section; existing API and data unchanged.')
print('No SQL migration required.')
